gWs(){return"\u0648\u0627\u062a\u0633\u0627\u0628"},
gQe(){return"\u062d\u0642\u0648\u0642 \u0627\u0644\u0646\u0634\u0631 (c) 2020-2025 Naji At Abu-Mousa. \u062c\u0645\u064a\u0639 \u0627\u0644\u062d\u0642\u0648\u0642 \u0645\u062d\u0641\u0648\u0638\u0629"},
gFA(){return"\u0633\u064a\u0627\u0633\u0629 \u0627\u0644\u062e\u0635\u0648\u0635\u064a\u0629"},
gFT(){return"\u0627\u0644\u0634\u0631\u0648\u0637 \u0648\u0627\u0644\u0623\u062d\u0643\u0627\u0645"},
gET(){return"\u062a\u0639\u0644\u0645 \u0627\u0644\u0622\u0644\u0629"},
gCK(){return"\u0627\u0644\u0630\u0643\u0627\u0621 \u0627\u0644\u0627\u0635\u0637\u0646\u0627\u0639\u064a"},
gQw(){return"\u0627\u0644\u062a\u0639\u0644\u0645 \u0627\u0644\u0639\u0645\u064a\u0642"},
gDt(){return"\u0623\u0646\u0638\u0645\u0629 \u062f\u0639\u0645 \u0627\u0644\u0642\u0631\u0627\u0631"},
gUA(){return"\u0628\u0627\u064a\u062b\u0648\u0646 (Streamlit)"},
gVL(){return"\u062a\u0637\u0628\u064a\u0642 \u0648\u064a\u0628 \u0644\u062a\u062d\u0644\u064a\u0644 \u0627\u0644\u0645\u062d\u0648\u0644\u0627\u062a"},
gOO(){return"\u0631\u0624\u0649 \u0645\u062f\u0639\u0648\u0645\u0629 \u0628\u0627\u0644\u0630\u0643\u0627\u0621 \u0627\u0644\u0627\u0635\u0637\u0646\u0627\u0639\u064a \n\u0644\u0625\u062a\u062e\u0627\u0630 \u0642\u0631\u0627\u0631\u0627\u062a \u0623\u0630\u0643\u0649 \ud83e\udde0"},
gOP(){return"\u062a\u0637\u0628\u064a\u0642 \u0648\u064a\u0628 \u0645\u0628\u0646\u064a \u0628\u0627\u0633\u062a\u062e\u062f\u0627\u0645 Streamlit \u064a\u0633\u062a\u0641\u064a\u062f \u0645\u0646 \u062a\u0642\u0646\u064a\u0627\u062a \u0627\u0644\u062a\u0639\u0644\u0645 \u0627\u0644\u0622\u0644\u064a \u0648\u0627\u0644\u0630\u0643\u0627\u0621 \u0627\u0644\u0627\u0635\u0637\u0646\u0627\u0639\u064a \u0644\u062a\u062d\u0644\u064a\u0644 \u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a\ud83d\udcca\u060c \u0648\u0627\u0643\u062a\u0634\u0627\u0641 \u0627\u0644\u0623\u0646\u0645\u0627\u0637\ud83d\udcac\u060c \u0648\u062f\u0639\u0645 \u0627\u062a\u062e\u0627\u0630 \u0627\u0644\u0642\u0631\u0627\u0631\ud83e\udde0. \u064a\u062a\u0636\u0645\u0646 \u0645\u064a\u0632\u0627\u062a \u0645\u062b\u0644 \u0627\u0644\u0646\u0645\u0630\u062c\u0629 \u0627\u0644\u062a\u0646\u0628\u0624\u064a\u0629\u060c \u0627\u0644\u0631\u0633\u0648\u0645 \u0627\u0644\u062a\u0641\u0627\u0639\u0644\u064a\u0629\u060c \u0648\u0648\u0627\u062c\u0647\u0629 \u0645\u0633\u062a\u062e\u062f\u0645 \u0633\u0644\u0633\u0629 \u0642\u0627\u0628\u0644\u0629 \u0644\u0644\u0648\u0635\u0648\u0644 \u0639\u0628\u0631 \u0627\u0644\u0623\u062c\u0647\u0632\u0629."},
gQr(){return"\u062a\u062d\u0644\u064a\u0644 \u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a"},
gUd(){return"\u0627\u0644\u0646\u0645\u0630\u062c\u0629 \u0627\u0644\u062a\u0646\u0628\u0624\u064a\u0629"},
